using System;
using Astrea.BattleActions;
using Astrea.RunModifiers;
using LittleLeo;
using LittleLeo.Events;
using LittleLeo.Variables;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "ChooseActionState", menuName = "Data/Battle/Game States/Choose Action State")]
public class ChooseActionState : GameState
{
	[Header("Spcefic Variables")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	[SerializeField]
	private PlayerCurrentRunes playerCurrentRunes;

	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private MapHandler mapHandler;

	[SerializeField]
	private ZoomableInstanceReference endTurnButtonZoomableInstanceReference;

	[Header("Events")]
	[SerializeField]
	private BoolEvent OnNoCorruptionOnPlayersHand;

	[NonSerialized]
	private bool corruptionSourcePurged;

	[NonSerialized]
	[ShowNonSerializedField]
	private bool endTurnAvailable;

	public ZoomableInstanceReference EndTurnButtonZoomableInstanceReference => endTurnButtonZoomableInstanceReference;

	public bool EndTurnAvailable => endTurnAvailable;

	public void SetEndTurnAvailable(bool value)
	{
		endTurnAvailable = value;
	}

	public void OnReset()
	{
		corruptionSourcePurged = false;
	}

	public void OnCorruptionSourcePurged()
	{
		corruptionSourcePurged = true;
	}

	public override void OnStartState()
	{
		base.OnStartState();
		Debug.Log("ChooseActionState OnStartState");
		ReferenceSingleton<AssetsReference>.Instance.DrawPool.ResetAllDiceJustPlayed();
		ReferenceSingleton<AssetsReference>.Instance.Discard.ResetAllDiceJustPlayed();
		ReferenceSingleton<GameplayHandler>.Instance.ResetTimeScale();
		if (mapHandler.CorruptionSourceBattle)
		{
			if (!corruptionSourcePurged)
			{
				Debug.Log("ChooseActionState corruptionSourcePurged false");
				InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
				{
					if (ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction != null)
					{
						if (!ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction())
						{
							OnNoCorruptionOnPlayersHand.Raise(!IsAnyMustUseDice());
						}
					}
					else
					{
						OnNoCorruptionOnPlayersHand.Raise(!IsAnyMustUseDice());
					}
				});
			}
			else
			{
				Debug.Log("ChooseActionState corruptionSourcePurged true");
				corruptionSourcePurged = false;
				OnNoCorruptionOnPlayersHand.Raise(item: false);
				ReferenceSingleton<GameStateManager>.Instance.TryEnterEndPlayerTurnStateIfNotEndOfBattleStateAlreadyCalled();
			}
		}
		else if (currentCorruptedAnimals.activeCorruptedAnimals.Count > 0)
		{
			Debug.Log("ChooseActionState activeEnemies > 0");
			InvokeAlternatives.InvokeAfterFrame(ReferenceSingleton<CoroutineHandler>.Instance, delegate
			{
				if (ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction != null)
				{
					if (!ReferenceSingleton<MiscOmensHandler>.Instance.SpicyLollipopOmenAction())
					{
						OnNoCorruptionOnPlayersHand.Raise(!IsAnyMustUseDice());
					}
				}
				else
				{
					OnNoCorruptionOnPlayersHand.Raise(!IsAnyMustUseDice());
				}
			});
		}
		else
		{
			OnNoCorruptionOnPlayersHand.Raise(item: false);
			ReferenceSingleton<GameStateManager>.Instance.TryEnterEndPlayerTurnStateIfNotEndOfBattleStateAlreadyCalled();
		}
	}

	private bool IsAnyMustUseDice()
	{
		if (ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.PerpetualClockOmenAction != null || ReferenceSingleton<RunModifiersManager>.Instance.GoddessTrickeryRunModifierActive || currentCorruptedAnimals.IsAphoticInstinctActiveAndWithNoDoom())
		{
			return false;
		}
		if (!ReferenceSingleton<PlayerDiceHandHolder>.Instance.IsAnyMustUseDice() && !currentCompanions.IsAnyMustUseDice())
		{
			return playerCurrentRunes.IsAnyMustUseAction();
		}
		return true;
	}
}
